"""Focused UI flow: clean export, measure-only generation, column defaults/order and tiles."""
import os,subprocess,tempfile,json
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
root=Path(__file__).resolve().parents[1]
with tempfile.TemporaryDirectory(prefix='cfs-clean-') as tmp:
 seed=json.loads(subprocess.check_output(['node','-e','process.stdout.write(JSON.stringify(require("./scripts/fixture").seed()))'],cwd=root))
 for group in [seed['remote'],{k[5:]:v for k,v in seed['docs'].items() if k.startswith('epic:')}]:
  for epic in group.values():epic['extra'].pop('Project__r.V2MOM_Method__c',None)
 data=Path(tmp)/'data.json';data.write_text(json.dumps(seed));server=subprocess.Popen(['node','server.js','--fixture'],cwd=root,env={**os.environ,'PORT':'8397','CFS_FIXTURE_FILE':str(data)},stdout=subprocess.PIPE,text=True)
 try:
  assert 'Release Review:' in server.stdout.readline()
  with sync_playwright() as p:
   browser=p.chromium.launch();page=browser.new_page(viewport={'width':1900,'height':1000});errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
   page.add_init_script("window.aiCalls=0;window.copied='';Object.defineProperty(navigator,'clipboard',{value:{writeText:async t=>{window.copied=t;}}});window.AppletAI={isAvailable:()=>true,complete:async(n,o)=>{window.aiCalls++;return {text:window.aiCalls===1?'The team reports: Done: Regional validation remains in progress.':'Regional validation remains in progress.',usage:{input_tokens:20,output_tokens:10}};}};")
   page.goto('http://127.0.0.1:8397');expect(page.locator('#epic-count')).to_have_text('6')
   headers=page.locator('#table-head th').all_text_contents();assert ['Epic Name','Development Lead','Epic Status','Review Status','Review Summary']==[h.replace('↑','').replace('↓','').replace('↕','').strip() for h in headers[1:]],headers
   tile_titles=page.locator('#health-metrics-strip>.metric .metric-header,#health-metrics-strip>.insight-card h3').all_text_contents();assert [s.strip() for s in tile_titles]==['Release scope','Story point delivery','Epic health','On track','Needs attention','Nov 2026 updates','Monthly coverage'],tile_titles
   assert page.locator('[data-view=overview]').evaluate('e=>parseFloat(getComputedStyle(e).fontSize)')==13
   row=page.locator('.epic-summary-row').first;expect(row.locator('.review-summary-cell button')).to_have_text('Summary');row.locator('.epic-expand-toggle').click();expect(row.locator('.review-summary-cell button')).to_have_count(0);detail=page.locator('.epic-expanded-table');assert not any(x in ['Epic Status','Review Status'] for x in detail.locator('th').all_text_contents())
   page.locator('#columns-button').click();expect(page.locator('#col-health')).not_to_be_checked();expect(page.locator('#col-reviewStatus')).not_to_be_checked();expect(page.locator('#col-health')).to_be_enabled();page.locator('#col-health').check();page.locator('#col-reviewStatus').check();page.locator('#save-columns').click();expect(page.locator('#drawer')).to_be_hidden();expect(page.locator('.epic-expanded-table')).to_contain_text('Epic Status');expect(page.locator('.epic-expanded-table')).to_contain_text('Review Status');page.reload();expect(page.locator('#epic-count')).to_have_text('6');page.locator('.epic-expand-toggle').first.click();expect(page.locator('.epic-expanded-table')).to_contain_text('Review Status')
   page.locator('[data-view=executive]').click();page.locator('#generate-executive').click();expect(page.locator('#generate-executive')).to_be_enabled(timeout=15000);expect(page.locator('.executive-blurb')).to_have_count(6);assert 'The team reports' not in page.locator('#executive-content').inner_text();assert page.locator('#executive-content .executive-kpis').count()==0;assert page.locator('#executive-content .health-badge').count()==0;page.locator('#copy-executive').click();copied=page.evaluate('window.copied');assert copied.count('Regional validation remains in progress.')==6,copied;assert 'M1.1.1' in copied;assert 'Managed Async Processing Service (MAPS)' in copied;assert not any(t in copied for t in ['SP closed','Path to Green:','The team reports','No dated engineer','Compliance:','On Track']),copied
   page.locator('#generate-method').click();expect(page.locator('#generate-method')).to_be_enabled(timeout=15000);expect(page.locator('#method-summary .method-team-update')).to_have_count(3);expect(page.locator('#method-summary')).to_contain_text('Consolidated Measure Updates');page.locator('#copy-method').click();copied=page.evaluate('window.copied');assert copied.count('M1.1.1')==1,copied;assert copied.count('Regional validation remains in progress.')==3,copied;assert 'Source summaries' not in copied;page.screenshot(path='/tmp/cfs-ga15-clean-executive.png',full_page=True);page.locator('[data-view=overview]').click();page.screenshot(path='/tmp/cfs-ga15-row-order.png',full_page=True);assert not errors,errors;browser.close();print('PASS measure-only AI correction, clean executive/measure clipboard, no KPI/context noise, row order/Summary header, default unchecked status preferences persist, compact tabs and exact tile order.')
 finally:server.terminate();server.wait(timeout=10)
